import numpy as np

def kernel(x, t, D=1):
    return np.exp(-x ** 2 / (4 * D * t)) / np.sqrt(4 * np.pi * D * t)

def heat_line_profile(u0, xs, t, D=1.0, n=8001):
    """u(x, t) for every x in xs."""
    xs = np.asarray(xs, dtype=float)
    b = np.abs(xs).max() + 10 * np.sqrt(2 * D * t)
    y = np.linspace(-b, b, n)
    h = y[1] - y[0]
    wt = np.full(n, h)
    wt[0] = wt[-1] = h / 2
    K = kernel(xs[:, None] - y[None, :], t, D) * u0(y)[None, :] * wt[None, :]
    return K.sum(axis=1)
